const row = $input.first()?.json;

if (!row) {
  throw new Error('Geen journal entry gevonden voor deze userId.');
}

const clean = (value) => typeof value === 'string' ? value.trim() : '';
const fallback = '(geen journal-inhoud gevonden)';
const sourceText = clean(row.ai_summary) || clean(row.edited_transcript) || clean(row.raw_transcript) || fallback;
const tomorrowFocus = clean(row.tomorrow_focus);
const createdAt = row.created_at ? new Date(row.created_at).toISOString() : new Date().toISOString();
const safeDate = clean(row.entry_date) || createdAt.slice(0, 10);
const compact = sourceText.replace(/\s+/g, ' ').trim() || fallback;
const maxBodyLength = 3400;
const snippet = compact.length > maxBodyLength ? `${compact.slice(0, maxBodyLength)}...` : compact;
const lines = [
  'JouwTDL journal test',
  `Datum: ${safeDate}`,
  '',
  'Inhoud:',
  snippet
];

if (tomorrowFocus) {
  lines.push('', `Focus morgen: ${tomorrowFocus}`);
}

return [
  {
    json: {
      message: lines.join('\n')
    }
  }
];
